import React from "react";
import vid from "./solarSection.mp4";
import SubHeading from "../../../Components/Heading/SubHeading";
import Paragraphs from "../../../Components/Heading/Paragraphs";
import Video from "../../../Components/Video/Video";

function Section3() {
  const title = "A Dynamic and Evolving System" 
     
    

  const body = "Today, the solar system is an active and interconnected system dominated"
        +"by the Sun, which provides energy and drives phenomena like solar winds"
        +"and magnetic storms. Earth continues to evolve geologically and"
        +"climatically, while Mars is a cold, dusty planet with signs of past water,"
        +"and Venus experiences extreme greenhouse effects. Humanity has expanded"
        +"its understanding of the solar system through exploration, sending rovers"
        +"to Mars, probes to the outer planets, and telescopes to study distant"
        +"objects like those in the Kuiper Belt. Monitoring of asteroids and comets"
        +"for potential collisions highlights the ongoing activity within the"
        +"system. Each celestial body, from planets to dwarf planets and moons,"
        +"plays a role in the dynamic balance that characterizes the solar system"
        +"today. sm:hidden md:flex";
    
  return (
    <div className="  w-full h-screen p-10 grid md:p-1 ">
      
      <Video path={vid} />
      <div className=" text-center p-3 text-xl md:w-1/2 md:pt-40 ">
        <SubHeading text={title} />
        <Paragraphs text={body}/>
      </div>
    </div>
  );
}

export default Section3;
